pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Give the contract 1 ether
        vm.deal(address(c), 1 ether);
        // Call sudicideAnyone() as owner
        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        // The reference version succeeds (selfdestruct sends balance to msg.sender) – balance becomes 0
        // The buggy version reverts after selfdestruct, so the balance remains 1 ether
        assertTrue(!ok || address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(address(c), 1 ether);
        vm.deal(owner, 0 ether);

        bool ok;
        vm.prank(owner);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // After reference call: contract selfdestructs -> address(c).balance == 0 and owner balance increases
        // After buggy call: contract still exists because revert after selfdestruct (selfdestruct is reverted) -> address(c).balance == 1 ether
        assertEq(address(c).balance, 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.deal(address(c), 1 ether);
        vm.prank(address(0x1));
        // Attempt to call the function from non-owner (should revert, but focus is on owner call)
        // Instead, fund the contract and call with owner
        vm.deal(address(c), 1 ether);
        vm.prank(address(this)); // deployer is owner
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        assertTrue(ok);
        // After reference: contract is destroyed, balance 0
        // After buggy: revert runs, selfdestruct ineffective, balance stays 1 ether
        assertEq(address(c).balance, 0 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 wei so we can check balance changes
        vm.deal(address(c), 1 ether);

        // Call sudicideAnyone() as the owner
        vm.prank(address(0x1234));
        // In setUp, __owner was set to msg.sender (the test contract), so prank as the test contract
        address testContract = address(this);
        vm.deal(testContract, 0); // not needed but safe
        vm.prank(testContract);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, reference version selfdestructs, so address(c).balance becomes 0
        // Second version reverts, so address(c).balance remains 1 ether
        assertEq(address(c).balance, 0);
    }
}

